1	package warranty
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件回归保障“取消承诺释放未用占用”这一既有功能，在另一个保修请求正为
11	// 同一种备件提交新预留时的并发正确性。业务主例：
12	//
13	//	备件 part1 初始库存十件；
14	//	cOld6：请求 rA 的承诺预留六件，已成功使用两件（已领取实物两件）；
15	//	cOther4：请求 rB 的承诺预留四件，尚未使用。
16	//	此时实物剩余八件、有效占用八件（cOld6 未用四件 + cOther4 四件）、
17	//	可承诺数量为零。
18	//
19	// 第三个具备保修资格的请求 rC 使用从未成功过的新承诺编号申请预留四件，这次
20	// 提交与取消 cOld6 同时发生，不预设谁先被处理。两种先后关系都合法：
21	//
22	//   - 新预留在取消生效前被处理：可承诺为零，返回 ErrInsufficientStock，不创建
23	//     新承诺、不留下任何占用；取消完成后实物八件、有效占用四件、可承诺四件。
24	//   - 取消先生效：cOld6 未用的四件被释放（已用两件不回补实物库存），新预留
25	//     成功，最终实物仍八件、有效占用八件、可承诺为零。
26	//
27	// 无论哪种结果，cOld6 最终都必须显示已取消并保留原定六件、已用两件、未用四件
28	// 及原到期时刻；cOther4 的状态、数量与归属不变；不能出现预留成功却没有对应
29	// 占用的结果。另覆盖取消释放后、四件尚未被新承诺占用时申请五件的边界。
30	// 这些测试只沿用登记、资格、预留、使用、取消与查询等既有公开入口、错误类别
31	// 及资格、到期和编号重试规则。
32	
33	const (
34		crPart     = "part1"
35		crReqOld   = "rA"
36		crReqOther = "rB"
37		crReqNew   = "rC"
38		crOld      = "cOld6"
39		crOther    = "cOther4"
40		crNew      = "cNew4"
41		crFive     = "cNew5"
42		crFour     = "cNew4b"
43		crUsage    = "uOldUsed2"
44	)
45	
46	var (
47		crExpiryOld   = t0.Add(40 * day)
48		crExpiryOther = t0.Add(30 * day)
49		crExpiryNew   = t0.Add(45 * day)
50		// crRaceNow 是取消与新预留并发提交的当前时刻，早于全部承诺到期时刻，
51		// 也在保修期内；查询沿用稍后但仍早于最早到期时刻的 crCheckNow。
52		crRaceNow  = nowOK.Add(time.Hour)
53		crCheckNow = crRaceNow.Add(time.Hour)
54	)
55	
56	// cancelReleaseStore 构造上述业务主例并断言取消前的初始账目：实物八件、
57	// 有效占用八件、可承诺为零。
58	func cancelReleaseStore(t *testing.T) *Store {
59		t.Helper()
60		s := NewStore()
61		if err := s.RegisterProduct("p1", t0, 30, nil); err != nil {
62			t.Fatalf("register product: %v", err)
63		}
64		if err := s.RegisterPart(crPart, 10); err != nil {
65			t.Fatalf("register part: %v", err)
66		}
67		for _, id := range []string{crReqOld, crReqOther, crReqNew} {
68			if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
69				t.Fatalf("submit request %s: %v", id, err)
70			}
71		}
72		if _, err := s.Reserve(crOld, crReqOld, crPart, 6, crExpiryOld, nowOK); err != nil {
73			t.Fatalf("reserve %s: %v", crOld, err)
74		}
75		if _, err := s.Reserve(crOther, crReqOther, crPart, 4, crExpiryOther, nowOK); err != nil {
76			t.Fatalf("reserve %s: %v", crOther, err)
77		}
78		if _, err := s.Use(crUsage, crOld, 2, nowOK); err != nil {
79			t.Fatalf("use 2 from %s: %v", crOld, err)
80		}
81		st, err := s.PartStatus(crPart, crCheckNow)
82		if err != nil {
83			t.Fatalf("part status baseline: %v", err)
84		}
85		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 8 || st.Committable != 0 {
86			t.Fatalf("baseline account: phys=%d occupied=%d committable=%d, want 8/8/0",
87				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
88		}
89		return s
90	}
91	
92	// crRaceResult 收集一次并发“取消 + 新预留”的两个返回值。
93	type crRaceResult struct {
94		canceled   Commitment
95		cancelErr  error
96		reserved   Commitment
97		reserveErr error
98	}
99	
100	// fanOutCancelReserve 让取消 cOld6 与新预留（新编号、四件）在同一道闸机释放后
101	// 同时进入仓库，尽量制造交叉；两者的实际先后不由测试预设。
102	func fanOutCancelReserve(t *testing.T, s *Store, newID string, now time.Time) crRaceResult {
103		t.Helper()
104		var rr crRaceResult
105		var wg sync.WaitGroup
106		start := make(chan struct{})
107	
108		wg.Add(1)
109		go func() {
110			defer wg.Done()
111			<-start
112			rr.canceled, rr.cancelErr = s.Cancel(crOld, now)
113		}()
114		wg.Add(1)
115		go func() {
116			defer wg.Done()
117			<-start
118			rr.reserved, rr.reserveErr = s.Reserve(newID, crReqNew, crPart, 4, crExpiryNew, now)
119		}()
120		close(start)
121		wg.Wait()
122		return rr
123	}
124	
125	// assertCancelReleaseFixedCommitments 核对与本次并发结果无关的既有事实：
126	// cOld6 已取消但保留原定六件、已用两件、未用四件、归属与原到期时刻，其成功
127	// 使用记录仍在（已领取实物不回库存）；cOther4 完全不受影响。
128	func assertCancelReleaseFixedCommitments(t *testing.T, s *Store) {
129		t.Helper()
130		old, err := s.Commitment(crOld)
131		if err != nil {
132			t.Fatalf("commitment %s: %v", crOld, err)
133		}
134		if !old.Canceled || old.Expired || old.Quantity != 6 || old.Used != 2 ||
135			old.Unused() != 4 || old.RequestID != crReqOld || old.PartID != crPart ||
136			!old.Expiry.Equal(crExpiryOld) {
137			t.Fatalf("old commitment after cancel: %+v, want canceled qty=6 used=2 unused=4", old)
138		}
139		// 已成功领取的两件实物保留为使用记录，取消不抹除它们。
140		usages, err := s.CommitmentUsages(crOld)
141		if err != nil {
142			t.Fatalf("usages of %s: %v", crOld, err)
143		}
144		if len(usages) != 1 || usages[0] != (Usage{ID: crUsage, CommitmentID: crOld, Quantity: 2}) {
145			t.Fatalf("usages of old commitment = %+v, want single 2-piece usage", usages)
146		}
147		other, err := s.Commitment(crOther)
148		if err != nil {
149			t.Fatalf("commitment %s: %v", crOther, err)
150		}
151		if other.Canceled || other.Expired || other.Quantity != 4 || other.Used != 0 ||
152			other.Unused() != 4 || other.RequestID != crReqOther || other.PartID != crPart ||
153			!other.Expiry.Equal(crExpiryOther) {
154			t.Fatalf("other commitment disturbed: %+v, want active qty=4 used=0", other)
155		}
156	}
