158	// assertCancelReleaseNewRequestHistory 核对 rC 的预留处理历史与实际结果一致：
159	// 只有一条记录，成功或库存不足失败（含处理前库存依据快照）二选一，资格依据
160	// 均为合格。
161	func assertCancelReleaseNewRequestHistory(t *testing.T, s *Store, succeeded bool, wantBasis StockBasis) {
162		t.Helper()
163		hist, err := s.RequestHistory(crReqNew)
164		if err != nil {
165			t.Fatalf("request history %s: %v", crReqNew, err)
166		}
167		if len(hist) != 1 {
168			t.Fatalf("rC history len = %d, want exactly 1 record", len(hist))
169		}
170		rec := hist[0]
171		if rec.Seq != 1 || rec.CommitID != crNew || rec.PartID != crPart ||
172			rec.Quantity != 4 || !rec.Expiry.Equal(crExpiryNew) || !rec.Now.Equal(crRaceNow) {
173			t.Fatalf("rC record submission fields = %+v", rec)
174		}
175		if rec.Eligibility == nil || !rec.Eligibility.Eligible || rec.Eligibility.Excluded ||
176			rec.Eligibility.RequestID != crReqNew || len(rec.Eligibility.Reasons) != 0 {
177			t.Fatalf("rC record eligibility = %+v, want eligible snapshot", rec.Eligibility)
178		}
179		if rec.StockBasis == nil ||
180			rec.StockBasis.PhysicalRemaining != wantBasis.PhysicalRemaining ||
181			rec.StockBasis.ActiveOccupied != wantBasis.ActiveOccupied ||
182			rec.StockBasis.Committable != wantBasis.Committable {
183			t.Fatalf("rC record stock basis = %+v, want %+v", rec.StockBasis, wantBasis)
184		}
185		if succeeded {
186			if !rec.Success || rec.Error != "" {
187				t.Fatalf("rC record = %+v, want success", rec)
188			}
189		} else {
190			if rec.Success || rec.Error != HistoryErrorInsufficientStock {
191				t.Fatalf("rC record = %+v, want insufficient_stock failure", rec)
192			}
193		}
194	}
