196	// assertCancelReleaseOutcome 在并发结束后核对全部不变量。succeeded 仅用于交叉
197	// 校验调用方对 rr.reserveErr 的分支判断；账目、明细、查询与历史的期望值全部
198	// 按仓库实际状态从该分支推导，不预设固定结果。
199	func assertCancelReleaseOutcome(t *testing.T, s *Store, rr crRaceResult, succeeded bool, now time.Time) {
200		t.Helper()
201	
202		// 取消无论先后都成功，返回值即显示已取消并保留全部原定/已用/未用事实。
203		if rr.cancelErr != nil {
204			t.Fatalf("concurrent cancel: %v", rr.cancelErr)
205		}
206		if !rr.canceled.Canceled || rr.canceled.Quantity != 6 || rr.canceled.Used != 2 ||
207			rr.canceled.Unused() != 4 || rr.canceled.RequestID != crReqOld ||
208			!rr.canceled.Expiry.Equal(crExpiryOld) {
209			t.Fatalf("cancel result = %+v, want canceled 6/used2/unused4", rr.canceled)
210		}
211	
212		st, err := s.PartStatus(crPart, now)
213		if err != nil {
214			t.Fatalf("part status after race: %v", err)
215		}
216		// 实物剩余始终为八：预留不扣实物，取消不回补已领取的两件。
217		if st.PhysicalRemaining != 8 {
218			t.Fatalf("physical remaining = %d, want 8", st.PhysicalRemaining)
219		}
220	
221		wantNew := Commitment{
222			ID:        crNew,
223			RequestID: crReqNew,
224			PartID:    crPart,
225			Quantity:  4,
226			Expiry:    crExpiryNew,
227		}
228	
229		switch {
230		case succeeded:
231			// 取消先生效：新预留成功并返回完整的首次承诺（已用为零、未取消）。
232			if rr.reserveErr != nil {
233				t.Fatalf("reserve after cancel released stock: %v", rr.reserveErr)
234			}
235			if rr.reserved != wantNew || rr.reserved.Used != 0 ||
236				rr.reserved.Canceled || rr.reserved.Expired {
237				t.Fatalf("new reserve result = %+v, want %+v", rr.reserved, wantNew)
238			}
239			// 实物八件、有效占用八件（cOther4 + cNew4）、可承诺为零。
240			if st.ActiveOccupied != 8 || st.Committable != 0 {
241				t.Fatalf("account on success branch: occupied=%d committable=%d, want 8/0",
242					st.ActiveOccupied, st.Committable)
243			}
244			if len(st.Details) != 3 {
245				t.Fatalf("part details len = %d, want 3 (old canceled + other + new)", len(st.Details))
246			}
247			dNew := mustDetailByID(t, st.Details, crNew)
248			if dNew.Status != CommitmentActive || dNew.RequestID != crReqNew ||
249				dNew.PartID != crPart || dNew.OriginalQuantity != 4 ||
250				dNew.UsedQuantity != 0 || dNew.RemainingQuantity != 4 ||
251				!dNew.Expiry.Equal(crExpiryNew) {
252				t.Fatalf("new detail = %+v, want active 4/0/4 for rC", dNew)
253			}
254			got, err := s.Commitment(crNew)
255			if err != nil || got != wantNew {
256				t.Fatalf("stored new commitment = %+v, err %v; want %+v", got, err, wantNew)
257			}
258			view, err := s.RequestView(crReqNew, now)
259			if err != nil {
260				t.Fatalf("request view rC: %v", err)
261			}
262			if view.Eligibility == nil || !view.Eligibility.Eligible || len(view.Commitments) != 1 ||
263				view.Commitments[0].CommitmentID != crNew || view.Commitments[0].Status != CommitmentActive {
264				t.Fatalf("rC view = elig %+v commitments %+v, want single active %s",
265					view.Eligibility, view.Commitments, crNew)
266			}
267			// 成功时处理前账目是取消后的 8/4/4。
268			assertCancelReleaseNewRequestHistory(t, s, true, StockBasis{8, 4, 4})
269	
270		case errors.Is(rr.reserveErr, ErrInsufficientStock):
271			// 新预留在取消生效前被处理：ErrInsufficientStock，返回空承诺，不创建记录。
272			if rr.reserved != (Commitment{}) {
273				t.Fatalf("failed reserve returned commitment = %+v, want empty", rr.reserved)
274			}
275			// 取消随后完成：实物八件、有效占用四件（只剩 cOther4）、可承诺四件。
276			if st.ActiveOccupied != 4 || st.Committable != 4 {
277				t.Fatalf("account on failure branch: occupied=%d committable=%d, want 4/4",
278					st.ActiveOccupied, st.Committable)
279			}
280			if len(st.Details) != 2 {
281				t.Fatalf("part details len = %d, want 2 (no failed new commitment)", len(st.Details))
282			}
283			if _, err := s.Commitment(crNew); !errors.Is(err, ErrNotFound) {
284				t.Fatalf("failed commitment lookup: got %v / err %v, want ErrNotFound", rr.reserved, err)
285			}
286			view, err := s.RequestView(crReqNew, now)
287			if err != nil {
288				t.Fatalf("request view rC: %v", err)
289			}
290			if view.Eligibility == nil || !view.Eligibility.Eligible || len(view.Commitments) != 0 {
291				t.Fatalf("rC view = elig %+v commitments %+v, want eligible with no commitments",
292					view.Eligibility, view.Commitments)
293			}
294			// 失败时处理前账目是取消前的 8/8/0。
295			assertCancelReleaseNewRequestHistory(t, s, false, StockBasis{8, 8, 0})
296	
297		default:
298			t.Fatalf("concurrent reserve returned unexpected error: %v (commitment %+v)",
299				rr.reserveErr, rr.reserved)
300		}
301	
302		// 备件明细中已取消的 cOld6 必须保留可追查，cOther4 保持有效；活动明细的
303		// 未用数量之和必须恰好等于有效占用，杜绝“预留成功却没有对应占用”。
304		dOld := mustDetailByID(t, st.Details, crOld)
305		if dOld.Status != CommitmentCanceled || dOld.RequestID != crReqOld ||
306			dOld.OriginalQuantity != 6 || dOld.UsedQuantity != 2 || dOld.RemainingQuantity != 4 ||
307			!dOld.Expiry.Equal(crExpiryOld) {
308			t.Fatalf("old detail = %+v, want canceled 6/2/4", dOld)
309		}
310		dOther := mustDetailByID(t, st.Details, crOther)
311		if dOther.Status != CommitmentActive || dOther.RequestID != crReqOther ||
312			dOther.OriginalQuantity != 4 || dOther.UsedQuantity != 0 || dOther.RemainingQuantity != 4 ||
313			!dOther.Expiry.Equal(crExpiryOther) {
314			t.Fatalf("other detail = %+v, want active 4/0/4", dOther)
315		}
316		activeUnused := 0
317		for _, d := range st.Details {
318			if d.Status == CommitmentActive {
319				activeUnused += d.RemainingQuantity
320			}
321		}
322		if activeUnused != st.ActiveOccupied {
323			t.Fatalf("active details unused sum = %d, want ActiveOccupied %d", activeUnused, st.ActiveOccupied)
324		}
325		if st.PhysicalRemaining-st.ActiveOccupied != st.Committable {
326			t.Fatalf("committable %d != physical %d - occupied %d",
327				st.Committable, st.PhysicalRemaining, st.ActiveOccupied)
328		}
329	
330		// 按请求查看：rA 仍只看到已取消的旧记录，rB 仍只看到自己未受影响的承诺。
331		viewA, err := s.RequestView(crReqOld, now)
332		if err != nil {
333			t.Fatalf("request view rA: %v", err)
334		}
335		if len(viewA.Commitments) != 1 {
336			t.Fatalf("rA commitments = %d, want 1 (canceled record retained)", len(viewA.Commitments))
337		}
338		if d := viewA.Commitments[0]; d.CommitmentID != crOld || d.Status != CommitmentCanceled ||
339			d.OriginalQuantity != 6 || d.UsedQuantity != 2 || d.RemainingQuantity != 4 ||
340			!d.Expiry.Equal(crExpiryOld) {
341			t.Fatalf("rA view of old commitment = %+v", d)
342		}
343		viewB, err := s.RequestView(crReqOther, now)
344		if err != nil {
345			t.Fatalf("request view rB: %v", err)
346		}
347		if len(viewB.Commitments) != 1 {
348			t.Fatalf("rB commitments = %d, want 1", len(viewB.Commitments))
349		}
350		if d := viewB.Commitments[0]; d.CommitmentID != crOther || d.Status != CommitmentActive ||
351			d.OriginalQuantity != 4 || d.UsedQuantity != 0 || d.RemainingQuantity != 4 ||
352			!d.Expiry.Equal(crExpiryOther) {
353			t.Fatalf("rB view changed after cancel/reserve race: %+v", d)
354		}
355	
356		// 取消与新预留都不向两个既有请求追加历史：各自只有建仓时的一条成功记录。
357		for _, rid := range []string{crReqOld, crReqOther} {
358			hist, err := s.RequestHistory(rid)
359			if err != nil {
360				t.Fatalf("history %s: %v", rid, err)
361			}
362			if len(hist) != 1 || !hist[0].Success {
363				t.Fatalf("history of %s = %+v, want single original success record", rid, hist)
364			}
365		}
366	
367		assertCancelReleaseFixedCommitments(t, s)
368	}
