370	// TestConcurrentCancelAndNewReserveEitherOrderValid 主并发回归：取消旧承诺与
371	// rC 的四件新预留同时发生，不预设处理先后。每次迭代允许出现任一合法结果
372	// （成功并占满释放量，或 ErrInsufficientStock 且取消后释放四件），但两种先后
373	// 关系下的全部账目、明细、查询与历史不变量都必须成立，不能出现成功却无占用
374	// 或失败却留下承诺等中间态。
375	func TestConcurrentCancelAndNewReserveEitherOrderValid(t *testing.T) {
376		const iterations = 50
377		var sawSuccess, sawFailure int
378		for i := 0; i < iterations; i++ {
379			t.Run("iteration", func(t *testing.T) {
380				s := cancelReleaseStore(t)
381				rr := fanOutCancelReserve(t, s, crNew, crRaceNow)
382				switch {
383				case rr.reserveErr == nil:
384					sawSuccess++
385				case errors.Is(rr.reserveErr, ErrInsufficientStock):
386					sawFailure++
387				default:
388					t.Fatalf("iteration: unexpected reserve error %v", rr.reserveErr)
389				}
390				assertCancelReleaseOutcome(t, s, rr, rr.reserveErr == nil, crCheckNow)
391			})
392		}
393		// 仅作信息记录：两种先后关系在足量迭代下通常都会真实发生；即使某次运行
394		// 调度只给出一侧，assertCancelReleaseOutcome 也已覆盖该侧的全部不变量。
395		t.Logf("across %d iterations: reserve-after-cancel successes=%d, reserve-before-cancel failures=%d",
396			iterations, sawSuccess, sawFailure)
397	}
