399	// TestReserveBeforeCancelFailsThenCancelReleasesFour 确定地覆盖“新预留先被
400	// 处理”的先后关系：可承诺为零时四件预留返回 ErrInsufficientStock 且不创建
401	// 承诺；随后取消完成，只释放旧承诺未用的四件，实物仍八件。失败不占用编号，
402	// 取消生效后用同一编号以相同内容再次提交应当成功（这是失败后的新提交，不是
403	// 幂等重试），最终账目与“取消先成功”一侧一致。
404	func TestReserveBeforeCancelFailsThenCancelReleasesFour(t *testing.T) {
405		s := cancelReleaseStore(t)
406	
407		// 取消尚未生效：可承诺为零，整次拒绝。
408		c, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, crRaceNow)
409		if !errors.Is(err, ErrInsufficientStock) || c != (Commitment{}) {
410			t.Fatalf("reserve before cancel: c=%+v err=%v, want ErrInsufficientStock", c, err)
411		}
412		if _, err := s.Commitment(crNew); !errors.Is(err, ErrNotFound) {
413			t.Fatalf("failed reserve created commitment: err=%v", err)
414		}
415		// 失败不改变账目：实物八件、占用八件、可承诺零。
416		if st, _ := s.PartStatus(crPart, crCheckNow); st.PhysicalRemaining != 8 ||
417			st.ActiveOccupied != 8 || st.Committable != 0 {
418			t.Fatalf("state after failed reserve: %+v, want 8/8/0", st)
419		}
420	
421		// 随后取消：释放未用四件，已用两件不回补实物。
422		canceled, err := s.Cancel(crOld, crRaceNow.Add(time.Minute))
423		if err != nil {
424			t.Fatalf("cancel after failed reserve: %v", err)
425		}
426		if !canceled.Canceled || canceled.Quantity != 6 || canceled.Used != 2 || canceled.Unused() != 4 {
427			t.Fatalf("cancel result = %+v", canceled)
428		}
429		st, _ := s.PartStatus(crPart, crCheckNow)
430		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
431			t.Fatalf("state after cancel: phys=%d occupied=%d committable=%d, want 8/4/4",
432				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
433		}
434	
435		// 失败记录不占用新编号：取消生效后用相同内容再次提交应当首次成功。
436		later := crCheckNow.Add(time.Hour)
437		got, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, later)
438		if err != nil {
439			t.Fatalf("resubmit same id after cancel: %v", err)
440		}
441		wantNew := Commitment{ID: crNew, RequestID: crReqNew, PartID: crPart, Quantity: 4, Expiry: crExpiryNew}
442		if got != wantNew {
443			t.Fatalf("resubmitted commitment = %+v, want %+v", got, wantNew)
444		}
445		st2, _ := s.PartStatus(crPart, later)
446		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 8 || st2.Committable != 0 {
447			t.Fatalf("state after resubmit: %+v, want phys=8 occupied=8 committable=0", st2)
448		}
449	
450		// rC 历史两条：先是取消前库存不足失败（依据 8/8/0），再是取消后成功
451		// （依据 8/4/4），序号连续，失败记录不是承诺、成功记录必有对应占用。
452		hist, err := s.RequestHistory(crReqNew)
453		if err != nil {
454			t.Fatalf("rC history: %v", err)
455		}
456		if len(hist) != 2 {
457			t.Fatalf("rC history len = %d, want 2", len(hist))
458		}
459		if hist[0].Seq != 1 || hist[0].Success || hist[0].Error != HistoryErrorInsufficientStock ||
460			hist[0].StockBasis == nil || hist[0].StockBasis.Committable != 0 {
461			t.Fatalf("rC failure record = %+v", hist[0])
462		}
463		if hist[1].Seq != 2 || !hist[1].Success || hist[1].Error != "" ||
464			hist[1].StockBasis == nil || hist[1].StockBasis.ActiveOccupied != 4 ||
465			hist[1].StockBasis.Committable != 4 {
466			t.Fatalf("rC success record = %+v", hist[1])
467		}
468	
469		assertCancelReleaseFixedCommitments(t, s)
470	}
