472	// TestCancelBeforeReserveSucceedsAndRetryRulesHold 确定地覆盖“取消先生效”的
473	// 先后关系：旧承诺未用四件释放后，rC 的四件预留成功，实物仍八件、可承诺归零。
474	// 新承诺随后沿用既有编号重试规则：相同内容原样取回首次承诺，不重复占用、不
475	// 追加历史；改数量即 ErrConflict，库存与归属不变。
476	func TestCancelBeforeReserveSucceedsAndRetryRulesHold(t *testing.T) {
477		s := cancelReleaseStore(t)
478	
479		if _, err := s.Cancel(crOld, crRaceNow); err != nil {
480			t.Fatalf("cancel before reserve: %v", err)
481		}
482		st, _ := s.PartStatus(crPart, crCheckNow)
483		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
484			t.Fatalf("state after cancel only: %+v, want 8/4/4", st)
485		}
486	
487		got, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, crRaceNow.Add(time.Minute))
488		if err != nil {
489			t.Fatalf("reserve freed four: %v", err)
490		}
491		wantNew := Commitment{ID: crNew, RequestID: crReqNew, PartID: crPart, Quantity: 4, Expiry: crExpiryNew}
492		if got != wantNew {
493			t.Fatalf("new commitment = %+v, want %+v", got, wantNew)
494		}
495	
496		// 原样重试（当前时刻不同也不影响）：取回首次承诺，不重复占用、不追加历史。
497		retryNow := crCheckNow.Add(time.Hour)
498		again, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, retryNow)
499		if err != nil || again != wantNew {
500			t.Fatalf("idempotent retry = %+v err %v, want %+v", again, err, wantNew)
501		}
502		st2, _ := s.PartStatus(crPart, retryNow)
503		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 8 || st2.Committable != 0 {
504			t.Fatalf("idempotent retry changed stock: %+v", st2)
505		}
506		hist, _ := s.RequestHistory(crReqNew)
507		if len(hist) != 1 || !hist[0].Success {
508			t.Fatalf("rC history after retry = %+v, want single success record", hist)
509		}
510	
511		// 改数量复用编号：ErrConflict，不改变库存与归属，冲突失败记录挂在 rC 下。
512		if conflict, err := s.Reserve(crNew, crReqNew, crPart, 5, crExpiryNew, retryNow); !errors.Is(err, ErrConflict) {
513			t.Fatalf("retry with changed quantity: c=%+v err=%v, want ErrConflict", conflict, err)
514		}
515		st3, _ := s.PartStatus(crPart, retryNow)
516		if st3.PhysicalRemaining != 8 || st3.ActiveOccupied != 8 || st3.Committable != 0 {
517			t.Fatalf("conflict retry changed stock: %+v", st3)
518		}
519		stored, err := s.Commitment(crNew)
520		if err != nil || stored != wantNew {
521			t.Fatalf("new commitment overwritten by conflict attempt: %+v err %v", stored, err)
522		}
523		hist2, _ := s.RequestHistory(crReqNew)
524		if len(hist2) != 2 || hist2[1].Success || hist2[1].Error != HistoryErrorConflict ||
525			hist2[1].Eligibility != nil || hist2[1].StockBasis != nil {
526			t.Fatalf("rC history after conflict = %+v, want appended conflict record with nil basis", hist2)
527		}
528	
529		assertCancelReleaseFixedCommitments(t, s)
530	}
531	
532	// TestAfterCancelFreedFourReserveFiveRejectedWhole 边界回归：取消释放后四件
533	// 尚未被新承诺占用（实物八件、有效占用四件、可承诺四件），第三张请求申请五件
534	// 必须整次拒绝：返回 ErrInsufficientStock，不创建承诺，实物库存与其他承诺的
535	// 占用均不改变。失败不消耗可承诺数量，随后申请恰好四件应成功。
536	func TestAfterCancelFreedFourReserveFiveRejectedWhole(t *testing.T) {
537		s := cancelReleaseStore(t)
538	
539		if _, err := s.Cancel(crOld, crRaceNow); err != nil {
540			t.Fatalf("cancel: %v", err)
541		}
542		st, _ := s.PartStatus(crPart, crCheckNow)
543		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
544			t.Fatalf("state after cancel: %+v, want 8/4/4", st)
545		}
546	
547		// 可承诺只有四件：申请五件整次拒绝。
548		c, err := s.Reserve(crFive, crReqNew, crPart, 5, crExpiryNew, crCheckNow)
549		if !errors.Is(err, ErrInsufficientStock) || c != (Commitment{}) {
550			t.Fatalf("reserve five against four committable: c=%+v err=%v, want ErrInsufficientStock", c, err)
551		}
552		if _, err := s.Commitment(crFive); !errors.Is(err, ErrNotFound) {
553			t.Fatalf("rejected five-piece reserve left a commitment: err=%v", err)
554		}
555	
556		// 实物库存、有效占用、可承诺数量与其他承诺均不改变。
557		st2, err := s.PartStatus(crPart, crCheckNow)
558		if err != nil {
559			t.Fatalf("part status after rejection: %v", err)
560		}
561		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 4 || st2.Committable != 4 {
562			t.Fatalf("rejected reserve changed stock: %+v, want 8/4/4", st2)
563		}
564		if len(st2.Details) != 2 {
565			t.Fatalf("details len = %d, want 2 (old canceled + other)", len(st2.Details))
566		}
567		assertCancelReleaseFixedCommitments(t, s)
568	
569		// 失败记录与实际预留一致：一条库存不足记录，处理前依据为 8/4/4。
570		hist, err := s.RequestHistory(crReqNew)
571		if err != nil {
572			t.Fatalf("rC history: %v", err)
573		}
574		if len(hist) != 1 || hist[0].Success || hist[0].Error != HistoryErrorInsufficientStock ||
575			hist[0].CommitID != crFive || hist[0].Quantity != 5 ||
576			hist[0].StockBasis == nil || hist[0].StockBasis.PhysicalRemaining != 8 ||
577			hist[0].StockBasis.ActiveOccupied != 4 || hist[0].StockBasis.Committable != 4 {
578			t.Fatalf("rC rejection record = %+v", hist)
579		}
580	
581		// 被整次拒绝没有消耗任何可承诺数量：另一个新编号申请恰好四件应当成功，
582		// 成功后实物仍八件、有效占用八件、可承诺为零。
583		later := crCheckNow.Add(time.Hour)
584		four, err := s.Reserve(crFour, crReqNew, crPart, 4, crExpiryNew, later)
585		if err != nil {
586			t.Fatalf("reserve exact four after five rejected: %v", err)
587		}
588		if four.Quantity != 4 || four.RequestID != crReqNew || four.Used != 0 ||
589			four.Canceled || four.Expired {
590			t.Fatalf("exact-four commitment = %+v", four)
591		}
592		st3, _ := s.PartStatus(crPart, later)
593		if st3.PhysicalRemaining != 8 || st3.ActiveOccupied != 8 || st3.Committable != 0 {
594			t.Fatalf("stock after exact-four reserve: %+v, want 8/8/0", st3)
595		}
596	}
597

